\documentclass{article}
\usepackage[paperwidth=841mm,paperheight=1189mm,margin=0mm]{geometry} % A0 portrait
\usepackage{tcolorbox}
\tcbuselibrary{poster,skins,fitting}
\usepackage{graphicx}
\usepackage{amsmath,amssymb}
\usepackage{enumitem}
\usepackage[table]{xcolor}
\usepackage{lmodern}
\usepackage[T1]{fontenc}
\pagestyle{empty}

% Dark Theme Colors
\definecolor{primary}{HTML}{0EA5E9}     % electric blue
\definecolor{secondary}{HTML}{10B981}   % teal
\definecolor{accent}{HTML}{F59E0B}      % warm amber
\definecolor{bgposter}{HTML}{0B1120}    % deep navy background
\definecolor{cardbg}{HTML}{1E293B}      % slate card background
\definecolor{cardtitlebg}{HTML}{0F172A} % darker slate for card titles
\definecolor{textdark}{HTML}{F8FAFC}    % white
\definecolor{textgray}{HTML}{94A3B8}    % gray
\definecolor{stathighlight}{HTML}{1E293B}
\definecolor{boxprimary}{HTML}{0C4A6E}
\definecolor{boxaccent}{HTML}{78350F}

\pagecolor{bgposter}
\color{textdark}

% List styling
\setlist[itemize]{leftmargin=30pt, itemsep=12pt, parsep=4pt, topsep=4pt,
  label={\color{secondary}$\blacktriangleright$}}
\setlist[enumerate]{leftmargin=30pt, itemsep=12pt, parsep=4pt, topsep=4pt,
  label={\color{primary}\bfseries\arabic*.}}

% Card styles
\tcbset{
  bluecard/.style={
    enhanced, arc=0pt, boxrule=0pt, colback=cardbg, colupper=textdark,
    borderline west={8pt}{0pt}{primary},
    left=24pt, right=24pt, top=16pt, bottom=16pt,
    fonttitle=\fontsize{40}{48}\selectfont\bfseries\color{primary},
    coltitle=primary, colbacktitle=cardtitlebg,
    toptitle=16pt, bottomtitle=16pt,
    titlerule=2pt, titlerule style={primary!50!black},
    valign=top, drop shadow={opacity=0.5, color=black},
  },
  tealcard/.style={
    enhanced, arc=0pt, boxrule=0pt, colback=cardbg, colupper=textdark,
    borderline west={8pt}{0pt}{secondary},
    left=24pt, right=24pt, top=16pt, bottom=16pt,
    fonttitle=\fontsize{40}{48}\selectfont\bfseries\color{secondary},
    coltitle=secondary, colbacktitle=cardtitlebg,
    toptitle=16pt, bottomtitle=16pt,
    titlerule=2pt, titlerule style={secondary!50!black},
    valign=top, drop shadow={opacity=0.5, color=black},
  },
  ambercard/.style={
    enhanced, arc=0pt, boxrule=0pt, colback=cardbg, colupper=textdark,
    borderline west={8pt}{0pt}{accent},
    left=24pt, right=24pt, top=16pt, bottom=16pt,
    fonttitle=\fontsize{40}{48}\selectfont\bfseries\color{accent},
    coltitle=accent, colbacktitle=cardtitlebg,
    toptitle=16pt, bottomtitle=16pt,
    titlerule=2pt, titlerule style={accent!50!black},
    valign=top, drop shadow={opacity=0.5, color=black},
  },
}

\begin{document}
\begin{tcbposter}[
  coverage={spread},
  poster={columns=3, rows=20, spacing=4mm},  % Adding slight spacing for dark theme aesthetics
]

% ══ TITLE BAR ══
\posterbox[
  enhanced, colback=cardtitlebg, colframe=primary, colupper=textdark,
  arc=0pt, boxrule=0pt,
  left=40pt, right=40pt, top=20pt, bottom=16pt,
  halign=center, valign=center,
  drop shadow={opacity=0.5, color=black}
]{name=title, column=1, span=3, between=top and row3}{
  {\fontsize{84}{100}\selectfont\bfseries Aider LLM Polyglot Coding Leaderboard 2025}\\[16pt]
  {\fontsize{42}{50}\selectfont Autonomous Code Editing Evaluation}\\[12pt]
  {\fontsize{30}{38}\selectfont\color{textgray} 6 Languages | 225 Exercism Challenges | coder.aider.io}
}

% ══ STATS BANNER ══
\posterbox[
  enhanced, colback=cardtitlebg, colupper=textdark, boxrule=0pt, arc=0pt,
  left=12pt, right=12pt, top=16pt, bottom=16pt,
  valign=center, borderline south={3pt}{0pt}{primary!50!black},
]{name=stats, column=1, span=3, between=row3 and row5}{
  \centering
  \begin{minipage}[c]{0.32\linewidth}\centering
    \fcolorbox{primary!40!black}{stathighlight}{\parbox{0.88\linewidth}{%
      \centering\vspace{16pt}%
      {\fontsize{66}{80}\selectfont\bfseries\color{primary} 88.0\%}\\[8pt]
      {\fontsize{26}{32}\selectfont\color{textdark} Top Score (GPT-5 high)}\vspace{16pt}%
    }}
  \end{minipage}\hfill
  \begin{minipage}[c]{0.32\linewidth}\centering
    \fcolorbox{accent!40!black}{stathighlight}{\parbox{0.88\linewidth}{%
      \centering\vspace{16pt}%
      {\fontsize{66}{80}\selectfont\bfseries\color{accent} \$29.08}\\[8pt]
      {\fontsize{26}{32}\selectfont\color{textdark} Highest Cost Run}\vspace{16pt}%
    }}
  \end{minipage}\hfill
  \begin{minipage}[c]{0.32\linewidth}\centering
    \fcolorbox{secondary!40!black}{stathighlight}{\parbox{0.88\linewidth}{%
      \centering\vspace{16pt}%
      {\fontsize{66}{80}\selectfont\bfseries\color{secondary} \$1.28}\\[8pt]
      {\fontsize{26}{32}\selectfont\color{textdark} Gemini 2.5 Flash (76.4\%)}\vspace{16pt}%
    }}
  \end{minipage}
}

% ══ CONTENT CARDS ══

\posterbox[tealcard, title={About the Benchmark}
]{name=about, column=1, between=row5 and row10}{
  \fontsize{34}{44}\selectfont
  \vspace{16pt}
  \begin{itemize}
    \item \textbf{Goal:} Evaluate autonomous code editing.
    \item \textbf{Scope:} 225 challenging Exercism tasks.
    \item \textbf{Languages:} C++, Go, Java, JS, Python, Rust.
    \item \textbf{Setup:} Zero human intervention allowed.
    \item \textbf{Metric:} \% of tests passing after 2 attempts.
  \end{itemize}
}

\posterbox[ambercard, title={Key Takeaways}
]{name=takeaways, column=1, between=row10 and row16}{
  \fontsize{34}{44}\selectfont
  \vspace{16pt}
  \begin{itemize}
    \item \textbf{GPT-5 Dominates:} 88.0\% accuracy but very high cost (\$29).
    \item \textbf{Anthropic Consistency:} Claude 4.0 models offer best format reliability (97\%).
    \item \textbf{Exceptional Value:} DeepSeek and Gemini provide >72\% accuracy for under \$5.
    \item \textbf{Format Matters:} Fenced diffs yield much more reliable edits.
  \end{itemize}
}

\posterbox[bluecard, title={Edit Format Compliance}
]{name=format, column=1, between=row16 and row20}{
  \fontsize{34}{44}\selectfont
  \vspace{16pt}
  Reliably following the requested diff format is critical for automated pipelines.\\[20pt]
  \colorbox{cardtitlebg}{\parbox{0.94\linewidth}{
    \vspace{8pt}
    \textbf{Diff-Fenced (93-97\%)} \\
    Claude models excel here, reaching up to 97.3\% compliance.
    \vspace{8pt}
  }}\\[20pt]
  \colorbox{cardtitlebg}{\parbox{0.94\linewidth}{
    \vspace{8pt}
    \textbf{Plain Diff (85-92\%)} \\
    OpenAI models use this, resulting in slightly lower reliability.
    \vspace{8pt}
  }}
}

\posterbox[bluecard, title={Top Models by Accuracy}
]{name=ranking, column=2, span=2, between=row5 and row14}{
  \vspace{16pt}
  \centering
  {\fontsize{30}{38}\selectfont
  \renewcommand{\arraystretch}{1.6}
  \begin{tabular}{p{2cm} p{8cm} c c c}
    \rowcolor{cardtitlebg}
    \textbf{Rank} & \textbf{Model} & \textbf{Correct} & \textbf{Cost} & \textbf{Format \%} \\
    \rowcolor{cardbg} 1 & GPT-5 (high) & \textbf{\color{secondary}88.0\%} & \$29.08 & 91.6\% \\
    \rowcolor{cardtitlebg} 2 & GPT-5 (medium) & \textbf{\color{secondary}86.7\%} & \$17.69 & 88.4\% \\
    \rowcolor{cardbg} 3 & Claude 4.0 Opus & \textbf{\color{secondary}85.3\%} & \$22.14 & \color{primary}97.3\% \\
    \rowcolor{cardtitlebg} 4 & Claude 4.0 Sonnet & \textbf{\color{secondary}84.0\%} & \$9.47 & \color{primary}96.9\% \\
    \rowcolor{cardbg} 5 & Gemini 2.5 Pro & \textbf{\color{secondary}82.7\%} & \$4.92 & \color{primary}95.1\% \\
    \rowcolor{cardtitlebg} 6 & o3 (high) & \textbf{82.2\%} & \$18.35 & 90.7\% \\
    \rowcolor{cardbg} 7 & GPT-5 (low) & \textbf{81.3\%} & \$8.12 & 85.8\% \\
    \rowcolor{cardtitlebg} 8 & DeepSeek R1-0528 & \textbf{80.4\%} & \$3.88 & 93.2\% \\
    \rowcolor{cardbg} 9 & Claude 3.7 Sonnet & \textbf{79.6\%} & \$7.81 & \color{primary}96.0\% \\
    \rowcolor{cardtitlebg} 10 & o3 (medium) & \textbf{78.7\%} & \$10.22 & 89.3\% \\
    \rowcolor{cardbg} 11 & Gemini 2.5 Flash & \textbf{76.4\%} & \textbf{\color{secondary}\$1.28} & 93.8\% \\
    \rowcolor{cardtitlebg} 12 & GPT-4.1 & \textbf{74.7\%} & \$5.60 & 88.0\% \\
    \rowcolor{cardbg} 13 & DeepSeek V3-0324 & \textbf{72.9\%} & \textbf{\color{secondary}\$1.95} & 91.5\% \\
    \rowcolor{cardtitlebg} 14 & Claude 3.5 Sonnet & \textbf{72.0\%} & \$6.33 & \color{primary}95.5\% \\
    \rowcolor{cardbg} 15 & o4-mini (high) & \textbf{71.1\%} & \$4.47 & 87.2\% \\
  \end{tabular}
  }
}

\posterbox[tealcard, title={Cost vs. Accuracy Trade-Off}
]{name=cost, column=2, span=2, between=row14 and row20}{
  \fontsize{34}{44}\selectfont
  \vspace{16pt}
  \textbf{High accuracy does not strictly require high spend.} The trade-off curve shows distinct tiers of value:\\[30pt]

  \centering
  \begin{minipage}{0.45\linewidth}
    \colorbox{boxprimary}{\parbox{0.94\linewidth}{
      \vspace{16pt}\centering
      \textbf{\color{primary} Premium Tier (>85\%)}\\[16pt]
      \fontsize{30}{40}\selectfont
      GPT-5 (high): 88.0\% @ \$29.08 \\
      GPT-5 (med): 86.7\% @ \$17.69 \\
      Claude 4 Opus: 85.3\% @ \$22.14
      \vspace{16pt}
    }}
  \end{minipage}\hfill
  \begin{minipage}{0.45\linewidth}
    \colorbox{boxaccent}{\parbox{0.94\linewidth}{
      \vspace{16pt}\centering
      \textbf{\color{accent} Value Tier (76-84\%)}\\[16pt]
      \fontsize{30}{40}\selectfont
      Claude 4 Sonnet: 84.0\% @ \$9.47 \\
      Gemini 2.5 Pro: 82.7\% @ \$4.92 \\
      DeepSeek R1: 80.4\% @ \$3.88 \\
      Gemini 2.5 Flash: 76.4\% @ \$1.28
      \vspace{16pt}
    }}
  \end{minipage}
  \\[40pt]
  \raggedright
  \textbf{The Takeaway:} For teams optimizing cost-efficiency, models in the \$1--\$5 range (Gemini 2.5 Flash, DeepSeek V3, Gemini 2.5 Pro) deliver robust performance for most real-world coding tasks at a fraction of the cost.
}

\end{tcbposter}
\end{document}
EOF

